Script.script:
-- ===== Galdam 전술 격자 뷰 v8: +오토타일 벽선/시야음영(fog)/벽그림자(AO)/바닥질감/애니 ===== GaldamTac = GaldamTac or {} local GT = GaldamTac GT.frame = GT.frame or 0 GT.flash = GT.flash or 0 GT.smoke = GT.smoke or {}
function GT.makeWindow() if not GT.win then GT.win = Geyser.MiniConsole:new({ name = "GaldamTacWin", x = "30%", y = "13%", width = 300, height = 320, autoWrap = false, scrollBar = false, fontSize = 12, color = "black" }) GT.win:setStyleSheet([[ background-color: rgba(10,12,18,242); border: 2px solid #5a8ac8; border-radius: 8px; ]]) GT.win:hide() end end -- 격자 전체를 한눈에: 창을 w×h에 맞춰 동적 resize (뷰포트 없음, 1칸 셀) function GT.fitWindow(w, h) if not GT.win then return end local fs = (w >= 36 or h >= 36) and 10 or ((w >= 30 or h >= 30) and 11 or ((w >= 22 or h >= 22) and 13 or 16)) local cw = math.ceil(fs * 0.72) -- 글자폭 넉넉히(우측 짤림 방지) local lh = fs + 6 local px = (w * 2 + 3) * cw + 24 -- 셀 가로 2칸 + 좌우 엣지 여유 local py = (h + 7) * lh + 22 -- 헤더+출구+범례 여유(상하 짤림 방지) pcall(function() GT.win:resize(px, py) end) pcall(function() GT.win:setFontSize(fs) end) -- 화면 중앙 정렬 (좌측 쏠림 방지, 35폭 대응) pcall(function() local mw, mh = getMainWindowSize() GT.win:move(math.max(8, math.floor((mw - px) / 2)), math.max(8, math.floor(mh * 0.10))) end) end if GaldamTacSprite then if GaldamTacSprite.h1 then pcall(killAnonymousEventHandler, GaldamTacSprite.h1); GaldamTacSprite.h1 = nil end if GaldamTacSprite.h2 then pcall(killAnonymousEventHandler, GaldamTacSprite.h2); GaldamTacSprite.h2 = nil end GaldamTacSprite.onTac = function() end GaldamTacSprite.onRoom = function() end if GaldamTacSprite.win then pcall(function() GaldamTacSprite.win:hide() end); pcall(function() GaldamTacSprite.win:setStyleSheet("background-color: rgba(0,0,0,0);") end) end end
local function clampc(v) return math.max(0, math.min(255, math.floor(v))) end local function dim(rgb, m) if m >= 0.999 then return rgb end local r, g, b = rgb:match("(%d+),(%d+),(%d+)") return clampc(tonumber(r)*m)..","..clampc(tonumber(g)*m)..","..clampc(tonumber(b)*m) end local function brighten(rgb) local r, g, b = rgb:match("(%d+),(%d+),(%d+)") return clampc(tonumber(r)+84)..","..clampc(tonumber(g)+84)..","..clampc(tonumber(b)+94) end -- 가로등 따뜻한 빛무리: 셀 색을 노란빛 쪽으로 끌어올림 (g=0~1 세기) local function warmGlow(rgb, g) local r, gr, b = rgb:match("(%d+),(%d+),(%d+)") r, gr, b = tonumber(r), tonumber(gr), tonumber(b) local k = g * 0.6 r = r + (255 - r ) * k * 0.95 gr = gr + (214 - gr) * k * 0.80 b = b + (140 - b ) * k * 0.45 return clampc(r)..","..clampc(gr)..","..clampc(b) end -- 임의 색 빛무리: 셀 색을 target(tr,tg,tb)쪽으로 끌어올림 (경광등 빨강/파랑용, a=0~1 세기) local function colorGlow(rgb, a, tr, tg, tb) local r, gr, b = rgb:match("(%d+),(%d+),(%d+)") r, gr, b = tonumber(r), tonumber(gr), tonumber(b) local k = a * 0.6 return clampc(r + (tr - r) * k) .. "," .. clampc(gr + (tg - gr) * k) .. "," .. clampc(b + (tb - b) * k) end -- 좌표 해시 미세 질감: 균일 바닥색을 ±5% 흔들어 흙/아스팔트 질감 (프레임 무관=정적) local function jitter(rgb, x, y) local n = (x * 53 + y * 97 + ((x * y) % 13) * 29) % 7 local f = 0.93 + 0.02 * n local r, g, b = rgb:match("(%d+),(%d+),(%d+)") return clampc(tonumber(r)*f) .. "," .. clampc(tonumber(g)*f) .. "," .. clampc(tonumber(b)*f) end local function smAdd(g, x, y, amt, t) local k = x .. "," .. y local c = g[k] if c then c.d = math.min(10, c.d + amt) else g[k] = { d = math.min(10, amt), t = t } end end
-- 연기 셀룰러 확산: emit(소스) → diffuse(이웃) → decay. 밀폐=잔류, 야외=흩어짐+바람 function GT.smokeStep(d) local w = tonumber(d.w) or 9 local h = tonumber(d.h) or 9 local outdoor = (d.biome == "forest" or d.biome == "road" or d.biome == "sea" or d.biome == "ocean" or d.biome == "village") local g = GT.smoke or {} for _, f in ipairs(d.fx or {}) do local x, y = tonumber(f.x), tonumber(f.y) -- 연기 차별화(2026-06-10): 화재=짙은회색 지속 / 담배=가는 흰 실연기(간헐 퍼프) / 김(steam)=모락모락 -- 최루(teargas)=녹색 광역 확산 / 폭발(blast)=순간 광역 퍼프 / 총(gunsmoke)=작은 한줌 if f.t == "fire" then if y-1 >= 0 then smAdd(g, x, y-1, 3.6, "gray") end elseif f.t == "smoke" then if (GT.frame % 6) < 2 and y-1 >= 0 then smAdd(g, x, y-1, 1.4, "white") end elseif f.t == "teargas" then smAdd(g, x, y, 9, "gas") elseif f.t == "breath" then if y-1 >= 0 then smAdd(g, x, y-1, 1.8, "white") end elseif f.t == "steam" then if (GT.frame % 4) < 3 and y-1 >= 0 then smAdd(g, x, y-1, 1.7, "white") end elseif f.t == "blast" then smAdd(g, x, y, 7.5, "gray"); smAdd(g, x-1, y, 3, "gray"); smAdd(g, x+1, y, 3, "gray"); smAdd(g, x, y-1, 3, "gray"); smAdd(g, x, y+1, 3, "gray") elseif f.t == "gunsmoke" then smAdd(g, x, y, 1.2, "gray") end end local spread = 0.5 local ng = {} for k, c in pairs(g) do local cx, cy = k:match("(%-?%d+),(%-?%d+)") cx, cy = tonumber(cx), tonumber(cy) local cd = (c.t == "gas") and 0.965 or (outdoor and 0.70 or 0.92) local dens = c.d * cd if dens > 0.35 then smAdd(ng, cx, cy, dens * (1 - spread), c.t) local nbrs if c.t == "gas" then nbrs = {{cx,cy-1,0.5},{cx,cy+1,1.2},{cx-1,cy,1.4},{cx+1,cy,1.4}} else nbrs = {{cx,cy-1,2.3},{cx,cy+1,0.5},{cx-1,cy,1},{cx+1,cy,1}} end if outdoor then nbrs[#nbrs+1] = {cx+1,cy,1.8} end local tot = 0 for _, nb in ipairs(nbrs) do tot = tot + nb[3] end local give = dens * spread for _, nb in ipairs(nbrs) do if nb[1] >= 0 and nb[1] < w and nb[2] >= 0 and nb[2] < h then smAdd(ng, nb[1], nb[2], give * nb[3] / tot, c.t) end end end end GT.smoke = ng end local function smokeActive() return next(GT.smoke or {}) ~= nil end
GT.GLYPH_MODE = "uni" -- "uni"|"ascii" — 폰트 실측 테스트(2026-06-07). 정렬 깨지면 "ascii"로 복귀 -- 타일 타입 → {u유니코드, a아스키, fg, bg}. 글리프는 데이터(타입)가 아니라 표현 — brief §2 GT.TILE = { -- terrain asphalt={u="\226\150\146",a=":",fg="86,91,97"}, dirt2={u="\226\150\145",a=".",fg="122,100,68"}, lane={u="\226\149\140",a="-",fg="207,200,159"}, lane_v={u="\226\149\142",a="|",fg="207,200,159"}, crosswalk={u="=",a="=",fg="232,230,227"}, field={u="~",a="~",fg="156,107,53"}, paddy={u="\226\137\161",a="=",fg="70,160,110"}, water={u="\226\137\136",a="~",fg="74,144,217"}, clearing={u="\194\183",a=".",fg="74,68,60"}, rockground={u="^",a="^",fg="138,144,151"}, concrete={u="·",a=".",fg="153,151,138"}, sand={u="·",a=".",fg="188,172,133"}, mudflat={u="≈",a="~",fg="123,115,91"}, pebbles={u="∴",a=":",fg="137,144,139"}, grass={u="'",a="'",fg="106,136,88"}, weed={u="\207\136",a="\"",fg="118,178,72"}, weed2={u="\206\189",a="'",fg="100,158,60"}, woodfloor={u=" ",a=" ",fg="120,90,56",bg="74,54,34"}, stairs_up={u="\226\150\179",a="^",fg="240,220,160",bg="74,54,34"}, stairs_down={u="\226\150\189",a="v",fg="160,130,80",bg="46,32,20"}, -- structure wall={u="\226\150\147",a="#",fg="166,98,78"}, house_wall={u="\226\150\147",a="#",fg="190,164,128"}, shed_wall={u="\226\150\147",a="#",fg="122,130,126"}, shop_wall={u="\226\150\147",a="#",fg="116,150,132"}, building={u="\226\150\147",a="#",fg="172,150,128"}, breakwater={u="\226\150\147",a="#",fg="138,141,146"}, fence={u="\226\150\145",a=":",fg="176,150,108"}, wall_h={u="\226\148\128",a="-",fg="216,205,184"}, wall_v={u="\226\148\130",a="|",fg="216,205,184"}, corner={u="+",a="+",fg="216,205,184"}, gate={u="\226\136\143",a="+",fg="210,165,80"}, door={u="\226\150\175",a="+",fg="210,165,80"}, window={u="\226\150\161",a="o",fg="127,184,216"}, window_open={u="\226\150\171",a="-",fg="150,220,235"}, window_broken={u="\226\128\187",a="*",fg="184,206,222"}, greenhouse={u="\226\136\169",a="n",fg="200,212,216"}, tetrapod={u="X",a="X",fg="125,132,138"}, lighthouse={u="I",a="I",fg="226,75,7