,gate_open=1} -- mask: N=1 E=2 S=4 W=8 (1~15) local BOXD = { "\226\149\145","\226\149\144","\226\149\154","\226\149\145","\226\149\145","\226\149\148","\226\149\160","\226\149\144","\226\149\157","\226\149\144","\226\149\169","\226\149\151","\226\149\163","\226\149\166","\226\149\172" } local BOXS = { "\226\148\130","\226\148\128","\226\148\148","\226\148\130","\226\148\130","\226\148\140","\226\148\156","\226\148\128","\226\148\152","\226\148\128","\226\148\180","\226\148\144","\226\148\164","\226\148\172","\226\148\188" } local PADD = "\226\149\144" -- ═ 셀 뒷칸 채움(가로 연속) local PADS = "\226\148\128" -- ─ -- returns: 글리프(or nil=원본유지), 뒷칸패딩(" " or 가로선) local function autoTile(struct, x, y) if GT.GLYPH_MODE ~= "uni" then return nil, " " end local s = struct[x .. "," .. y] if not s then return nil, " " end local t = s.t local fam = (WALLFAM[t] and WALLFAM) or (FENCEFAM[t] and FENCEFAM) or nil if not fam then -- 문/창문/대문: 글리프는 자기 것, 동쪽이 같은 줄이면 패딩으로 선 연속 if SCONN[t] then local e = struct[(x + 1) .. "," .. y] local et = e and e.t if et and (WALLFAM[et] or SCONN[et]) then return nil, PADD elseif et and FENCEFAM[et] then return nil, PADS end end return nil, " " end local function lk(nx, ny) local n = struct[nx .. "," .. ny] return (n and (fam[n.t] or SCONN[n.t])) and 1 or 0 end local eC = lk(x + 1, y) local m = lk(x, y - 1) + eC * 2 + lk(x, y + 1) * 4 + lk(x - 1, y) * 8 if m == 0 then return nil, " " end -- 고립 기둥=원본 블록 유지 local box = (fam == WALLFAM) and BOXD or BOXS local padc = (eC == 1) and ((fam == WALLFAM) and PADD or PADS) or " " return box[m], padc end -- 플레이어 시야 차단(fog of war) / 그림자 드리우는 구조물 local FOGSOLID = { wall=1, house_wall=1, shed_wall=1, shop_wall=1, building=1, breakwater=1, wall_h=1, wall_v=1, corner=1, door=1, gate=1, lighthouse=1, greenhouse=1 } for _,k in ipairs({"window_head","door_head","facade_sign_police_0","facade_sign_police_1","facade_sign_police_2","facade_sign_police_3","facade_sign_police_4","facade_sign_police_5","facade_sign_police_6","facade_si