4","facade_sign_pub_5","facade_sign_pub_6","facade_sign_market_0","facade_sign_market_1","facade_sign_market_2","facade_sign_market_3","facade_sign_market_4","facade_sign_market_5","facade_sign_market_6","facade_sign_tackle_0","facade_sign_tackle_1","facade_sign_tackle_2","facade_sign_tackle_3","facade_sign_tackle_4","facade_sign_tackle_5","facade_sign_tackle_6","facade_sign_warehouse_0","facade_sign_warehouse_1","facade_sign_warehouse_2","facade_sign_warehouse_3","facade_sign_warehouse_4","facade_sign_warehouse_5","facade_sign_warehouse_6","facade_sign_security_0","facade_sign_security_1","facade_sign_security_2","facade_sign_security_3","facade_sign_security_4","facade_sign_security_5","facade_sign_security_6"}) do AOSHADOW[k]=1 end for _,k in ipairs({"roof_blue","roof_gray","roof_tile","roof_flat","facade_home","facade_shop","facade_civic"}) do AOSHADOW[k]=1 end
-- facing {fx,fy} → 방향 화살표 글리프 (1칸폭) function GT.arrowOf(fx, fy) fx = tonumber(fx) or 0; fy = tonumber(fy) or 0 if fx > 0 and fy < 0 then return "\226\134\151" -- ↗ 북동 elseif fx > 0 and fy > 0 then return "\226\134\152" -- ↘ 남동 elseif fx < 0 and fy > 0 then return "\226\134\153" -- ↙ 남서 elseif fx < 0 and fy < 0 then return "\226\134\150" -- ↖ 북서 elseif fx > 0 then return "\226\150\182" -- ▶ 동 elseif fx < 0 then return "\226\151\128" -- ◀ 서 elseif fy > 0 then return "\226\150\188" -- ▼ 남 elseif fy < 0 then return "\226\150\178" -- ▲ 북 else return "v" end end
-- Real ceiling fixtures arrive separately: never infer them from cover or names. local function realStreetLamp(c) local id=tonumber(c.id) return c.k=="lamp" and id and id>0 and (c.on==true or tonumber(c.on)==1) end local function realLights(d) local out,seen={},{} local w,h=tonumber(d.w) or 9,tonumber(d.h) or 9 for _,c in ipairs(d.lights or {}) do local id,x,y=tonumber(c.id),tonumber(c.x),tonumber(c.y) if c.k=="ceiling_light" and id and id>0 and id==math.floor(id) and not seen[id] and x and y and x==math.floor(x) and y==math.floor(y) and x>=0 and y>=0 and x<w and y<h then out[#out+1]={id=id,x=x,y=y,on=(c.on==true or tonumber(c.on)==1),n=c.n or "천장 전등",k=c.k} seen[id]=true end end return out end
-- Diffuse skylight is transmitted by the server; indoor weather stays sheltered. local function skyLightLevel(d,lights,x,y,sx,sy,litrad) local level=tonumber(d.daylight) if not level then return nil end local v=math.max(0,math.min(1,level/100)) for _,light in ipairs(lights) do if light.on then local dist=math.sqrt((x-light.x)^2+(y-light.y)^2) if dist<=6 then v=math.max(v,0.96-dist*0.12) end end end if litrad>0 and sx and sy then local dist=math.max(math.abs(x-sx),math.abs(y-sy)) if dist<=litrad+1 then v=math.max(v,1-dist/(litrad+1.7)) end end return math.min(1,v) end
function GT.present() if GT.win then GT.win:show() end if GaldamAtlas and GaldamAtlas.bringToFront then GaldamAtlas.bringToFront() end if GaldamActivityArt then GaldamActivityArt.front() end end -- Conservative grid rays: walls in either native geometry layer occlude actors and overlays. local function makeVision(d) local opaque={};local blockers={wall=1,wall_h=1,wall_v=1,corner=1,building=1,breakwater=1,door=1,gate=1,greenhouse=1,lighthouse=1,house_wall=1,shed_wall=1,shop_wall=1,wall_stone=1,hull=1,roof_blue=1,roof_gray=1,roof_tile=1,roof_flat=1,facade_home=1,facade_shop=1,facade_civic=1,window_head=1,door_head=1} for _,list in ipairs({d.cover or {},d.struct or {}})do for _,e in ipairs(list)do local k=e.t or e.k or '';opaque[e.x..','..e.y]=(blockers[k] or k:match('^facade_sign_')) and true or nil end end local function blocked(x,y)return opaque[x..','..y]end local function clear(x,y,tx,ty) if not(x and y and tx and ty)then return false end local nx,ny=math.abs(tx-x),math.abs(ty-y);local sx,sy=tx>x and 1 or -1,ty>y and 1 or -1;local ix,iy=0,0 while ix<nx or iy<ny do local a,b=(1+2*ix)*ny,(1+2*iy)*nx if a==b then if blocked(x+sx,y) or blocked(x,y+sy)then return false end x=x+sx;y=y+sy;ix=ix+1;iy=iy+1 elseif a<b then x=x+sx;ix=ix+1 else y=y+sy;iy=iy+1 end if (x~=tx or y~=ty) and blocked(x,y)then return false end end return true end local fog={};local sx,sy=d.self and tonumber(d.self[1]),d.self and tonumber(d.self[2]);local radius=math.max(d.w or 9,d.h or 9) -- player display: no NPC senses cap if sx and sy then for y=0,(d.h or 9)-1 do for x=0,(d.w or 9)-1 do if math.max(math.abs(x-sx),math.abs(y-sy))>radius or not clear(sx,sy,x,y)then fog[x..','..y]=true end end end end return fog,clear end
function GT.render(d) local w = tonumber(d.w) or 9 local h = tonumber(d.h) or 9 local biome = d.biome or "indoor" local tone = tonumber(d.tone) or 3 local dark = tonumber(d.dark) or 0 local litrad = tonumber(d.litrad) or 0 local weather = d.weather or "clear" local floor = d.floor or "ondol" local outdoor = tonumber(d.outdoor)==1 or (d.outdoor==nil and (biome == "forest" or biome == "road" or biome == "sea" or biome == "ocean" or biome == "village")) local watery = (biome == "sea" or biome == "ocean") local flash = (GT.flash or 0) > 0 local watch = (tonumber(d.watch) or 0) == 1 -- 경계상황(실내/알림/수배/잠입)에서만 평시 원뿔 표시 local sx = d.self and tonumber(d.self[1]) local sy = d.self and tonumber(d.self[2]) GT.fitWindow(w, h) GT.win:clear() local nm = (gmcp.Galdam and gmcp.Galdam.Room and gmcp.Galdam.Room.name) or "전술 격자"
if (not outdoor) and not tonumber(d.daylight) and dark >= 1 and litrad <= 0 then GT.win:decho("<70,72,86> \226\140\150 ???\n\n") for i = 1, math.floor(h/2) do GT.win:decho("<11,11,15>" .. string.rep("\226\150\146", w) .. "\n") end GT.win:decho("\n<120,120,140> 너무 어두워 아무것도\n<120,120,140> 보이지 않는다...\n") GT.win:decho("<90,84,70> (라이터나 손전등이 필요하다)\n") return end
local lights,lightList={},realLights(d) for _,c in ipairs(lightList) do lights[c.x..","..c.y]=c end local cover, actors, ground, fire, items = {}, {}, {}, {}, {} local struct, terr = {}, {} for _, s in ipairs(d.struct or {}) do struct[tonumber(s.x)..","..tonumber(s.y)] = s end for _, t in ipairs(d.terrain or {}) do terr[tonumber(t.x)..","..tonumber(t.y)] = t end for _, c in ipairs(d.cover or {}) do cover[tonumber(c.x)..","..tonumber(c.y)] = c end for _, a in ipairs(d.actors or {}) do actors[tonumber(a.x)..","..tonumber(a.y)] = a end for _, it in ipairs(d.items or {}) do items[tonumber(it.x)..","..tonumber(it.y)] = it end for _, g in ipairs(d.ground or {}) do ground[tonumber(g.x)..","..tonumber(g.y)] = g end for _, f in ipairs(d.fx or {}) do if f.t == "fire" then fire[tonumber(f.x)..","..tonumber(f.y)] = true end end -- 지붕(실내) rect: 비/눈 파티클 안 그림 (서버 tac_roof → "roof":[[x1,y1,x2,y2],..]) local roofR = d.roof or {} local function roofed(cx, cy) for _, r in ipairs(roofR) do local x1, y1, x2, y2 = tonumber(r[1]), tonumber(r[2]), tonumber(r[3]), tonumber(r[4]) if x1 and cx >= x1 and cy >= y1 and cx <= x2 and cy <= y2 then return true end end return false end -- 상호작용 객체 맵: 셀 -> {{id,name,kind},...} (가구/아이템/액터, id>0만 클릭가능) local cellObj = {} local function _addObj(cx, cy, id, nm, kind) id = tonumber(id) if not (cx and cy and id and id > 0) then return end local k = cx .. "," .. cy cellObj[k] = cellObj[k] or {} table.insert(cellObj[k], { id = tostring(id), name = nm or "?", kind = kind }) end for _, a in ipairs(d.actors or {}) do _addObj(tonumber(a.x), tonumber(a.y), a.id, a.n, "actor") end for _, it in ipairs(d.items or {}) do local vehicle=it.sprite=="boat" and tonumber(it.entity_id) and tonumber(it.entity_id)>0 local id=(vehicle and tonumber(it.action_id) and tonumber(it.action_id)>0) and it.action_id or it.id _addObj(tonumber(it.x), tonumber(it.y), id, it.n, vehicle and "vehicle" or "item") end for _, c in ipairs(d.cover or {}) do _addObj(tonumber(c.x), tonumber(c.y), c.id, c.n, "furniture") end for _,c in ipairs(lightList) do _addObj(c.x,c.y,c.id,c.n,"light") end GT.cellObj = cellObj -- 인접(체비셰프≤1) 상호작용 객체 id 집합 → 우측패널 하이라이트용 GaldamTac.nearIds = {} if sx and sy then for k, objs in pairs(cellObj) do local cx, cy = k:match("(%-?%d+),(%-?%d+)") cx, cy = tonumber(cx), tonumber(cy) if cx and math.max(math.abs(cx - sx), math.abs(cy - sy)) <= 1 then for _, o in ipairs(objs) do GaldamTac.nearIds[o.id] = true end end end end if GaldamUI and GaldamUI.refreshNearHighlight then pcall(GaldamUI.refreshNearHighlight) end local ex = {} for _, e in ipairs(d.exits or {}) do ex[e.edge] = e.dir end local smoke = GT.smoke or {}
-- 플레이어 시야 음영(fog of war): 시선이 벽에 막힌 셀은 어둑하게. -- 데이터 갱신/위치 변경시에만 재계산(onTac이 fogKey 무효화), 애니 프레임은 캐시 재사용 local fog,clearSight=makeVision(d) GT.fog=fog
local OUTAMB = {[1]=0.40, [2]=0.85, [3]=1.0, [4]=0.50, [5]=0.28, [6]=0.16} local function lightMul(x, y) if not outdoor then local sky=skyLightLevel(d,lightList,x,y,sx,sy,litrad) if sky then return sky end if dark < 1 then return 1.0 end if litrad <= 0 or not sx then return 0.0 end local R = litrad + 1 local dist = math.max(math.abs(x - sx), math.abs(y - sy)) if dist > R then return 0.0 end return math.max(0.14, 1.0 - dist / (R + 0.7)) end -- 실외: 밤엔 광원 밖이 거의 암흑(FOW). 광원/플레이어 시야만 또렷 local amb = OUTAMB[tone] or 1.0 if weather == "fog" then amb = math.min(amb, 0.58) elseif weather == "storm" then amb = amb * 0.40 elseif weather == "rain" then amb = amb * 0.72 end local v = amb -- 플레이어 기본 시야(광원 없어도 주변 2칸 어렴풋 — 완전암흑 이동불가 방지) if sx then local pd = math.max(math.abs(x - sx), math.abs(y - sy)) if pd <= 4 then v = math.max(v, 0.58 - pd * 0.05) end end -- 손전등(litrad): 넓은 시야 if litrad > 0 and sx then local d2 = math.max(math.abs(x - sx), math.abs(y - sy)) if d2 <= litrad + 1 then v = math.max(v, 1.0 - d2 / (litrad + 1.7)) end end if sx and (weather == "fog" or weather == "storm") then local d3 = math.max(math.abs(x - sx), math.abs(y - sy)) local vis = (weather == "fog") and 6 or 3 if d3 > vis then v = v * math.max(0.15, 1 - (d3 - vis) * 0.10) end end return math.min(1.0, v) end local TONE = { [1]={0.70,8,6,26},[2]={0.90,14,11,5},[3]={1.00,0,0,0},[4]={0.84,28,9,0},[5]={0.66,52,14,2},[6]={0.40,2,6,32} } local function tint(rgb) if not outdoor then return rgb end local t = TONE[tone] or TONE[3] local r, g, b = rgb:match("(%d+),(%d+),(%d+)") r = clampc(tonumber(r)*t[1]+t[2]); g = clampc(tonumber(g)*t[1]+t[3]); b = clampc(tonumber(b)*t[1]+t[4]) if weather == "fog" then r=clampc(r*0.55+58); g=clampc(g*0.55+59); b=clampc(b*0.55+61) elseif weather == "storm" then r=clampc(r*0.58+6); g=clampc(g*0.62+11); b=clampc(b*0.68+22) end return r..","..g..","..b end local function floorBg(x, y) if outdoor then if biome == "road" then local v=(x*7+y*11)%4; return ({"38,38,42","44,44,49","33,33,37","41,41,46"})[v+1] elseif watery then local v=(x+y+math.floor((GT.frame or 0)/3))%4; return ({"18,52,78","22,60,92","15,46,70","26,66,100"})[v+1] elseif biome == "village" then local v=(x*7+y*11+x*y)%4; return ({"58,49,37","64,55,41","52,44,33","60,64,46"})[v+1] else local v=(x*7+y*11+x*y)%4; return ({"18,40,20","23,48,25","15,34,17","20,44,22"})[v+1] end end local v = (x*5+y*7)%3 if floor == "wood" then return ({"46,35,24","52,41,29","41,31,21"})[v+1] elseif floor == "hardwood" then return ({"78,56,34","86,62,38","70,50,30"})[v+1] elseif floor == "tile" then return ((x+y)%2==0) and "54,58,66" or "46,50,58" elseif floor == "marble" then return ((x+y)%2==0) and "80,82,88" or "70,72,79" elseif floor == "stone" then return ({"54,54,58","61,61,65","48,48,52"})[v+1] elseif floor == "concrete" then return ({"40,42,46","45,47,51","37,39,43"})[v+1] elseif floor == "carpet" then return ({"66,28,30","74,32,34","60,25,27"})[v+1] elseif floor == "carpet_blue" then return ({"30,40,64","34,45,70","26,36,58"})[v+1] elseif floor == "carpet_green" then return ({"32,54,42","36,60,46","28,48,38"})[v+1] elseif floor == "linoleum" then return ((x+y)%2==0) and "98,97,88" or "92,91,82" elseif floor == "dirt" then return ({"54,44,32","60,49,36","48,39,28"})[v+1] else return ({"104,98,62","112,106,68","96,90,56"})[v+1] end end local function cellBg(x, y) if fire[x..","..y] then return "70,26,8" end local sm = smoke[x..","..y] if sm and sm.d >= 3 then local op = math.min(0.7, sm.d/12) local base = (sm.t=="gas") and {150,150,90} or ((sm.t=="white") and {180,182,188} or {95,95,102}) local fb = floorBg(x,y); local r,g,b = (outdoor and tint(fb) or fb):match("(%d+),(%d+),(%d+)") return clampc(tonumber(r)*(1-op)+base[1]*op)..","..clampc(tonumber(g)*(1-op)+base[2]*op)..","..clampc(tonumber(b)*(1-op)+base[3]*op) end local g = ground[x..","..y] if g and g.t == "blood" then local l=tonumber(g.l) or 1; return (32+l*24)..",9,11" elseif g and g.t == "wet" then return "24,38,58" elseif g and g.t == "snow" then return "70,76,88" end return tint(jitter(floorBg(x, y), x, y)) end
local part = {} if outdoor and (weather == "rain" or weather == "snow" or weather == "storm") then local storm = (weather == "storm") local n = storm and math.floor(w*0.95) or ((weather=="rain") and math.floor(w*0.55) or math.floor(w*0.38)) for i = 1, n do local sp = (weather=="snow") and 1 or (storm and 3 or 2) local col = (i*5+3) % w if weather == "snow" then col = (col + math.floor(GT.frame/4)) % w elseif storm then col = (col + GT.frame) % w end local prow = ((i*3)+GT.frame*sp) % h if not roofed(col, prow) then part[col .. "," .. prow] = weather end end end
-- 가로등 빛무리: 야간 outdoor에서 lamp 주변 반경을 따뜻하게 + 아른거림(flicker) local glow = {} local glowOn = outdoor and ({[1]=0.26, [4]=0.40, [5]=0.58, [6]=0.75})[tone] if glowOn and glowOn > 0 then for _, c in ipairs(d.cover or {}) do if realStreetLamp(c) then local lx, ly = tonumber(c.x), tonumber(c.y) local fl = 0.86 + 0.14 * math.sin((GT.frame or 0) * 0.45 + lx * 1.7 + ly * 0.9) local R = 2 for ddy = -R, R do for ddx = -R, R do local gx, gy = lx + ddx, ly + ddy if gx >= 0 and gx < w and gy >= 0 and gy < h then local dist = math.max(math.abs(ddx), math.abs(ddy)) local v = (1 - dist / (R + 1)) * glowOn * fl if v > 0 then local gk = gx .. "," .. gy glow[gk] = math.min(1.0, (glow[gk] or 0) + v) end end end end end end end
-- 경찰차 경광등 빛무리: 점멸 위상에 따라 빨강/파랑이 주변으로 옅게 퍼짐 (야간일수록 강함) local pbGlow = {} local beaconOn = outdoor and ({[1]=0.34, [4]=0.50, [5]=0.66, [6]=0.85})[tone] if beaconOn and beaconOn > 0 then local on = math.floor((GT.frame or 0) / 3) % 2 local pulse = 0.72 + 0.28 * math.abs(math.sin((GT.frame or 0) * 0.9)) local tr = (on == 0) and 245 or 64 local tg = (on == 0) and 58 or 104 local tb = (on == 0) and 58 or 245 for _, c in ipairs(d.cover or {}) do if c.k == "policeL" or c.k == "policeR" then local lx, ly = tonumber(c.x), tonumber(c.y) local R = 3 for ddy = -R, R do for ddx = -R, R do local gx, gy = lx + ddx, ly + ddy if gx >= 0 and gx < w and gy >= 0 and gy < h then local dist = math.abs(ddx) + math.abs(ddy) local v = (1 - dist / (R + 1.5)) * beaconOn * pulse if v > 0 then local gk = gx .. "," .. gy local e = pbGlow[gk] if not e or v > e.v then pbGlow[gk] = {v = math.min(1.0, v), r = tr, g = tg, b = tb} end end end end end end end end
local function actorVisible(x,y) return x and y and not fog[x..","..y] and lightMul(x,y)>=0.28 end GT.visibleRoom=d.rid;GT.visibleIds={};GT.nearIds={} for key,list in pairs(cellObj)do local x,y=key:match("(%-?%d+),(%-?%d+)");x,y=tonumber(x),tonumber(y) if actorVisible(x,y)then for _,o in ipairs(list)do GT.visibleIds[tostring(o.id)]=true;if sx and math.max(math.abs(x-sx),math.abs(y-sy))<=1 then GT.nearIds[tostring(o.id)]=true end end else cellObj[key]=nil;actors[key]=nil end end -- NPC 시야 원뿔 (코만도스식): facing+시야로 cone 셀에 누적. 평시 초록, 의심↑ 주황→빨강 local cone = {} for _, a in ipairs(d.actors or {}) do if a.k == "npc" and a.f then local ox, oy = tonumber(a.x), tonumber(a.y) local fxv, fyv = tonumber(a.f[1]), tonumber(a.f[2]) local sr = tonumber(a.sr) or 5 local ct = tonumber(a.ct) or 1 local sus = tonumber(a.sus) or 0 -- 경계상황(watch)이거나 의심중인 NPC만 원뿔 표시. 평시 공개장소=숨김 if ox and fxv and actorVisible(ox,oy) and (watch or sus > 0) and (fxv ~= 0 or fyv ~= 0) then for cyy = 0, h - 1 do for cxx = 0, w - 1 do local vx, vy = cxx - ox, cyy - oy local dist = math.max(math.abs(vx), math.abs(vy)) if dist >= 1 and dist <= sr then local fdot = fxv * vx + fyv * vy local fcr = fxv * vy - fyv * vx if ((ct<=0 and fdot>=0) or (ct>0 and fdot>0 and math.abs(fcr)<=fdot*ct)) and actorVisible(cxx,cyy) and clearSight(ox,oy,cxx,cyy) then local k = cxx .. "," .. cyy local inten = (1 - dist / (sr + 1.5)) * 0.55 local e = cone[k] if not e or inten > e.v then cone[k] = { v = inten, sus = sus } end end end end end end end end
local hdr = outdoor and "<150,210,150>" or "<154,208,255>" local tnames = {"새벽","아침","낮","저녁","노을","밤"} GT.win:decho(hdr .. " \226\140\150 " .. nm) if outdoor then local sub = "(" .. (tnames[tone] or "") .. ")" if weather=="rain" then sub=sub.." 비" elseif weather=="snow" then sub=sub.." 눈" elseif weather=="fog" then sub=sub.." 안개" elseif weather=="storm" then sub=sub.." 태풍!" end GT.win:decho("<120,128,148> " .. sub) elseif dark >= 1 then GT.win:decho("<150,140,90> (불빛)") end GT.win:decho("\n") if ex.N then GT.win:decho("<150,255,150> \226\150\178 " .. ex.N .. "\n") else GT.win:decho("\n") end local fcol = {"255,150,32","255,92,20","255,205,70"} local midy = math.floor(h / 2) for y = 0, h - 1 do if y == midy and ex.W then GT.win:decho("<150,255,150>\226\151\128") else GT.win:decho(" ") end for x = 0, w - 1 do local key = x .. "," .. y local lm = lightMul(x, y) if lm <= 0.04 then GT.win:decho("<8,8,11:5,5,8> ") else local bg = cellBg(x, y) -- 벽 그림자(AO): 북쪽 이웃이 키 큰 구조물이면 남쪽(화면 아래) 셀 어둑하게 → 입체감 if not struct[key] then local ns = struct[x .. "," .. (y - 1)] if ns and AOSHADOW[ns.t] then bg = dim(bg, 0.76) elseif ns and FENCEFAM[ns.t] then bg = dim(bg, 0.88) end end local g = ground[key] local p = part[key] local sm = smoke[key] local fg, glyph local pad = " " if sx == x and sy == y then fg, glyph = "120,235,255", "@" elseif actors[key] then local a = actors[key] if a.k == "npc" then local sus = tonumber(a.sus) or 0 -- 시선 화살표는 평시에도 상시 표시 (원뿔만 경계상황 전용) if a.f and GT.arrowOf then glyph = GT.arrowOf(tonumber(a.f[1]), tonumber(a.f[2])) else glyph = "v" end if sus >= 61 then fg = "255,80,60" elseif sus >= 31 then fg = "255,150,60" elseif sus >= 1 then fg = "255,205,90" else fg = "230,200,90" end elseif a.k == "player" then fg, glyph = "120,230,120", "P" else fg, glyph = "255,90,90", "W" end elseif fire[key] then fg = fcol[((GT.frame + x + y) % 3) + 1] glyph = (((GT.frame + x) % 2) == 0) and "*" or "^" elseif sm and sm.d > 0.4 then local dd = sm.d local sv = (sm.t=="gas") and "190,190,110" or ((sm.t=="white") and "215,218,226" or "140,140,148") glyph = (dd>=5) and "#" or ((dd>=3) and ":" or ((dd>=1.5) and "." or "\194\176")) fg = sv elseif p == "rain" then fg, glyph = "120,170,225", "|" elseif p == "storm" then fg, glyph = "165,195,235", "/" elseif p == "snow" then fg, glyph = "230,235,245", "*" elseif items[key] then fg = "255,216,84" local it=items[key] local vehicle=it.sprite=="boat" and tonumber(it.entity_id) and tonumber(it.entity_id)>0 glyph = vehicle and "舟" or ((((math.floor((GT.frame or 0) / 4) + x + y) % 7) == 0) and "+" or "*") elseif struct[key] then local gg, sfg, sbg = glyphOf(struct[key].t); fg, glyph = tint(sfg), gg if sbg then bg = tint(sbg) end local at, ap = autoTile(struct, x, y) if at then glyph = at end pad = ap elseif cover[key] then local gg, cfg, cbg = glyphOf(cover[key].k); fg, glyph = tint(cfg), gg if cbg then bg = tint(cbg) elseif terr[key] then local _c1, _c2, ctb = glyphOf(terr[key].t); if ctb then bg = tint(ctb) end end elseif lights[key] then fg,glyph=lights[key].on and "255,246,182" or "126,139,132", lights[key].on and "⊕" or "⊗" elseif g and g.t == "blood" then local l = tonumber(g.l) or 1 glyph = (l>=5) and "#" or ((l>=2) and ":" or ".") fg = (115+l*20)..",26,28" elseif g and g.t == "wet" then fg, glyph = "90,150,210", "~" elseif g and g.t == "snow" then fg, glyph = "225,232,244", "\226\151\166" elseif g and g.t == "glass" then local l = tonumber(g.l) or 1 glyph = (l>=3) and "\226\128\187" or ((l>=2) and ":" or "\194\183") fg = "172,202,226" elseif g and g.t == "mess" then local l = tonumber(g.l) or 1 glyph = (l>=2) and ";" or "," fg = "150,120,82" elseif terr[key] then local gg, tfg, tbg = glyphOf(terr[key].t); fg, glyph = tint(tfg), gg; if tbg then bg = tint(tbg) end elseif outdoor then if biome == "road" then fg, glyph = tint("90,76,54"), " " elseif watery then local ph = (x + y*2 + (GT.frame or 0)) % 5 if ph < 2 then fg, glyph = tint("90,165,205"), "~" else fg, glyph = tint("60,120,165"), "~" end else -- 풀 살랑임: 다른 애니가 돌 때만 프레임이 흘러 무비용 (정지시 정적) local gp = (x*3 + y*5 + math.floor((GT.frame or 0) / 6)) % 5 if gp == 0 then fg, glyph = tint("78,130,62"), "," else fg, glyph = tint("40,82,44"), "." end end else if floor == "wood" or floor == "hardwood" then fg = "84,68,48"; glyph = "-" elseif floor == "tile" or floor == "marble" then fg = "104,108,118"; glyph = "." elseif floor == "stone" then fg = "82,82,86"; glyph = "." elseif floor == "concrete" then fg = "66,68,74"; glyph = ((x*3+y) % 5 == 0) and ":" or "." elseif floor == "carpet" or floor == "carpet_blue" or floor == "carpet_green" then fg = "150,140,135"; glyph = "\194\176" elseif floor == "linoleum" then fg = "120,118,108"; glyph = "." elseif floor == "dirt" then fg = "92,78,58"; glyph = ((x+y*2) % 4 == 0) and "," or "." else fg = "138,128,92"; glyph = "." end end local ffg, fbg = dim(fg, lm), dim(bg, lm) if flash then ffg = brighten(ffg); fbg = brighten(fbg) end local gl = glow[key] if gl and gl > 0.02 then local cc = cover[key] if not (cc and (cc.k == "policeL" or cc.k == "policeR")) then ffg = warmGlow(ffg, gl); fbg = warmGlow(fbg, gl * 0.6) end end local pb = pbGlow[key] if pb and pb.v > 0.03 then local cc2 = cover[key] if not (cc2 and (cc2.k == "policeL" or cc2.k == "policeR")) then ffg = colorGlow(ffg, pb.v, pb.r, pb.g, pb.b); fbg = colorGlow(fbg, pb.v * 0.7, pb.r, pb.g, pb.b) end end local cn = cone[key] if cn and cn.v > 0.03 and not (cover[key] and (cover[key].k == "policeL" or cover[key].k == "policeR")) then local cr, cg, cb = 70, 200, 90 if cn.sus >= 61 then cr, cg, cb = 235, 70, 60 elseif cn.sus >= 31 then cr, cg, cb = 235, 150, 60 elseif cn.sus >= 1 then cr, cg, cb = 220, 200, 70 end -- 원뿔 숨쉬는 펄스 (애니 타이머 도는 동안) local cpulse = 0.86 + 0.14 * math.sin((GT.frame or 0) * 0.45) fbg = colorGlow(fbg, cn.v * cpulse, cr, cg, cb) end -- 시야 음영 적용: 벽 너머는 어둑하게 (자기 칸은 항상 밝게) if fog and fog[key] and not (sx == x and sy == y) then ffg = dim(ffg, 0.40); fbg = dim(fbg, 0.42) end local _pk = cover[key] and cover[key].k if (_pk == "policeL" or _pk == "policeR") and not (sx == x and sy == y) then -- 경찰차: 칸당 2글자, 좌칸=[차체][빨강] 우칸=[파랑][차체] → 가운데2글자=경광등 점멸 local on = math.floor((GT.frame or 0) / 3) % 2 local body = dim("172,178,190", lm) if flash then body = brighten(body) end local red = (on == 0) and "240,46,46" or "82,26,30" local blu = (on == 1) and "54,96,240" or "26,34,82" if fog and fog[key] then body = dim(body, 0.42); red = dim(red, 0.42); blu = dim(blu, 0.42) end local c1 = (_pk == "policeL") and body or blu local c2 = (_pk == "policeL") and red or body local r1, g1, b1 = c1:match("(%d+),(%d+),(%d+)") local r2, g2, b2 = c2:match("(%d+),(%d+),(%d+)") pcall(function() GT.win:setFgColor(20, 22, 28); GT.win:setBgColor(tonumber(r1), tonumber(g1), tonumber(b1)) GT.win:echoLink(" ", "", "경찰차", true) GT.win:setFgColor(20, 22, 28); GT.win:setBgColor(tonumber(r2), tonumber(g2), tonumber(b2)) GT.win:echoLink(" ", "", "경찰차", true) end) else local _objs = cellObj[key] local thint = nil -- 일반 바닥(terr)은 툴팁 제외 — 가구(cover)/벽·문(struct)만 (사용자 요청 2026-06-11) if cover[key] then thint = GT.NAME[cover[key].k] elseif struct[key] then thint = GT.NAME[struct[key].t] end if _objs and #_objs > 0 and not (sx == x and sy == y) then local hint, lua if #_objs == 1 then hint = _objs[1].name lua = "GaldamUI.tacClick([[" .. _objs[1].id .. "]],[[" .. _objs[1].name .. "]])" else local nms = {} for _, oo in ipairs(_objs) do nms[#nms + 1] = oo.name end hint = "여러 개 (" .. #_objs .. "): " .. table.concat(nms, ", ") lua = "GaldamUI.tacStack(" .. x .. "," .. y .. ")" end local fr, fgc, fb = ffg:match("(%d+),(%d+),(%d+)") local br, bgc, bb = fbg:match("(%d+),(%d+),(%d+)") pcall(function() GT.win:setFgColor(tonumber(fr), tonumber(fgc), tonumber(fb)) GT.win:setBgColor(tonumber(br), tonumber(bgc), tonumber(bb)) GT.win:echoLink(glyph .. pad, lua, hint, true) end) elseif thint and not (sx == x and sy == y) then local fr, fgc, fb = ffg:match("(%d+),(%d+),(%d+)") local br, bgc, bb = fbg:match("(%d+),(%d+),(%d+)") pcall(function() GT.win:setFgColor(tonumber(fr), tonumber(fgc), tonumber(fb)) GT.win:setBgColor(tonumber(br), tonumber(bgc), tonumber(bb)) local tree=cover[key] and tostring(cover[key].k):find("tree",1,true) and (d.biome=="forest" or d.biome=="woods") and lm>=0.28 and not (fog and fog[key]) local roomId=tostring((gmcp.Galdam.Room or {}).roomid or "") local action="" if tree and roomId:match("^#%d+$") then action="GaldamUI.workTreeMenu("..x..","..y..",[["..roomId.."]])" end GT.win:echoLink(glyph .. pad, action, thint, true) end) else GT.win:decho("<" .. ffg .. ":" .. fbg .. ">" .. glyph .. pad) end end end end if y == midy and ex.E then GT.win:decho("<150,255,150>\226\150\182") end GT.win:echo("\n") end if ex.S then GT.win:decho("<150,255,150> \226\150\188 " .. ex.S .. "\n") else GT.win:decho("\n") end GT.win:decho("<120,130,150> @\235\130\152 N/X NPC/\236\160\129 \226\153\160\235\130\152\235\172\180 \226\151\143\235\176\148\236\156\132 \226\151\134\236\149\132\236\157\180\237\133\156\n (\236\149\132\236\157\180\236\189\152 \237\129\180\235\166\173=\236\131\129\237\152\184\236\158\145\236\154\169, \235\167\136\236\154\176\236\138\164=\237\136\180\237\140\129)\n") end
local function fxActive(d) return d and d.fx and type(d.fx)=="table" and #d.fx > 0 end -- 환경 빛 애니메이션 필요 여부: 야간 가로등 빛무리 or 경찰차 경광등 점멸 local function envAnim(d) if not d then return false end -- 시야 원뿔 표시중(경계/의심 NPC)이면 펄스 애니 local watch = (tonumber(d.watch) or 0) == 1 for _, a in ipairs(d.actors or {}) do if a.k == "npc" and a.f and (watch or (tonumber(a.sus) or 0) > 0) then return true end end if not d.cover then return false end local outdoor = (d.biome=="forest" or d.biome=="road" or d.biome=="sea" or d.biome=="ocean" or d.biome=="village") local tone = tonumber(d.tone) or 3 local nightLamp = outdoor and (tone == 1 or tone >= 4) for _, c in ipairs(d.cover) do if c.k == "policeL" or c.k == "policeR" then return true end if nightLamp and realStreetLamp(c) then return true end end return false end function GT.weatherTick() if not GT.lastData then GT.wtimer = nil; return end local d = GT.lastData local wx = d.weather local anim = (wx == "rain" or wx == "snow" or wx == "storm") or fxActive(d) or smokeActive() or (d.biome == "sea" or d.biome == "ocean") or envAnim(d) if not anim then GT.wtimer = nil; return end GT.frame = (GT.frame or 0) + 1 if (GT.flash or 0) > 0 then GT.flash = GT.flash - 1 end if wx == "storm" and (GT.flash or 0) <= 0 and math.random(100) <= 5 then GT.flash = 2 end if (GT.frame % 2) == 0 then GT.smokeStep(d) end if GT.win and GT.shown then GT.render(d) end GT.wtimer = tempTimer(0.12, "GaldamTac.weatherTick()") end
function GT.onTac() local d = gmcp.Galdam and gmcp.Galdam.Tac if not d then return end GT.fogKey = nil -- 새 데이터 = 구조물 변동 가능 → 시야 음영 재계산 GT.makeWindow(); GT.lastData = d -- 타일뷰 ON이면 글리프 뷰는 양보 (타일뷰 블록이 자체 렌더) if GaldamTileView and GaldamTileView.on then GT.win:hide(); GT.shown = false; return end GT.render(d); GT.present(); GT.shown = true local wx = d.weather local anim = (wx == "rain" or wx == "snow" or wx == "storm") or fxActive(d) or smokeActive() or (d.biome == "sea" or d.biome == "ocean") or envAnim(d) if anim and not GT.wtimer then GT.wtimer = tempTimer(0.12, "GaldamTac.weatherTick()") end end
function GT.onRoom() -- 같은 룸 Room 재푸시(내용물 변화)면 뷰 유지 — 무조건 숨김이 "화면 사라짐" 원인이었음 local rids = gmcp.Galdam and gmcp.Galdam.Room and gmcp.Galdam.Room.roomid local rid = rids and tonumber((tostring(rids):gsub("#", ""))) or nil if rid and rid == GT.curRoom then return end GT.curRoom = rid if GT.win then GT.win:hide() end GT.shown = false GT.smoke = {} GT.fog = nil; GT.fogKey = nil if GT.wtimer then killTimer(GT.wtimer); GT.wtimer = nil end end
if GT.h1 then killAnonymousEventHandler(GT.h1) end if GT.h2 then killAnonymousEventHandler(GT.h2) end GT.h1 = registerAnonymousEventHandler("gmcp.Galdam.Tac", "GaldamTac.onTac") GT.h2 = registerAnonymousEventHandler("gmcp.Galdam.Room", "GaldamTac.onRoom") GT.makeWindow() echo("[Galdam] 전술 격자 뷰 v8 로드됨 (+오토타일 벽선/시야음영/벽그림자/바닥질감/풀·원뿔 애니).\n")
